import{_ as o,o as n,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-04-02:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-04-02:: Crimson SeaStor OSD Weekly Meeting","date":"2019-04-02T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","Crimson 存储性能","性能测试","性能瓶颈","架构差异"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-02_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-04-02_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-04-02_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function t(s,i,_,a,m,p){return n(),e("div",null,[...i[0]||(i[0]=[l("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Kamijo Schoen, Ricardo, Dock, 其他研发人员</p><p><strong>会议主题</strong>： Crimson 存储性能测试及改进方案讨论</p><p><strong>关键细节</strong>：</p><ul><li>Kamijo Schoen汇报了Crimson存储性能测试结果，与经典存储相比，Crimson在4K随机读取方面性能提升约50%-60%。</li><li>测试结果显示，Crimson在处理小数据块时表现良好，但在处理大数据块时性能有所下降。</li><li>Kamijo Schoen指出，Crimson的性能瓶颈可能与日志记录和资源监控（如等待激活状态）有关。</li><li>会议讨论了Crimson与经典存储在架构上的差异，并强调了避免重复经典存储错误的必要性。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>Crimson性能提升</strong>： <ul><li>Kamijo Schoen分享了Crimson在4K随机读取方面的性能提升，并建议进一步测试和验证。</li><li>会议讨论了Crimson在处理不同类型数据时的性能表现，并分析了性能瓶颈的可能原因。</li></ul></li><li><strong>性能瓶颈分析</strong>： <ul><li>会议分析了Crimson在日志记录和资源监控方面的性能瓶颈，并提出了改进方案。</li><li>Kamijo Schoen建议使用帧指针支持进行性能分析，并关注等待激活状态和资源监控。</li></ul></li><li><strong>架构差异</strong>： <ul><li>会议讨论了Crimson与经典存储在架构上的差异，并强调了避免重复经典存储错误的重要性。</li><li>会议建议在巴塞罗那会议上讨论Crimson的宏观模块结构。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Kamijo Schoen将继续测试Crimson，并尝试优化性能。</li><li>会议建议使用帧指针支持进行性能分析，并关注等待激活状态和资源监控。</li><li>会议建议在巴塞罗那会议上讨论Crimson的宏观模块结构。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Kamijo Schoen将优化Crimson性能，并尝试解决性能瓶颈。</li><li>会议将关注Crimson的架构设计，并避免重复经典存储的错误。</li><li>会议将在巴塞罗那会议上讨论Crimson的宏观模块结构。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的关键术语包括：Crimson存储、经典存储、4K随机读取、日志记录、资源监控、帧指针支持、宏观模块结构等。</li></ul>",14)])])}const C=o(r,[["render",t]]);export{S as __pageData,C as default};
